package process

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// Harness writes ~700 KiB to stdout in one burst and exits immediately.
// The reader is artificially slowed via the Progress sink, mirroring a
// scheduler-stalled drain loop. Per os/exec docs it is incorrect to call
// Wait before all pipe reads complete; Run() calls Wait concurrently.
func TestBurstOutputTailLoss(t *testing.T) {
	dir := t.TempDir()
	payload := strings.Repeat("x", 700*1024)
	if err := os.WriteFile(filepath.Join(dir, "big.bin"), []byte(payload), 0o644); err != nil {
		t.Fatal(err)
	}
	losses := 0
	runs := 10
	for i := 0; i < runs; i++ {
		result, err := (DirectRunner{}).Run(context.Background(), Request{
			Executable: "/bin/cat", Args: []string{filepath.Join(dir, "big.bin")},
			Dir: dir, Env: []string{"PATH=/usr/bin:/bin"}, Timeout: 30 * time.Second,
			Progress: func(Event) { time.Sleep(8 * time.Millisecond) },
		})
		if err != nil {
			t.Fatalf("run %d: %v", i, err)
		}
		if result.ExitCode != 0 || result.TimedOut || result.Cancelled {
			t.Fatalf("run %d unexpected state: %+v", i, result)
		}
		if len(result.Stdout) != len(payload) {
			losses++
			t.Logf("run %d: captured %d of %d bytes (truncated flag=%v)", i, len(result.Stdout), len(payload), result.StdoutTruncated)
		}
		if result.StdoutTruncated && len(result.Stdout) < len(payload) {
			t.Logf("run %d: flagged truncated", i)
		}
	}
	if losses > 0 {
		t.Fatalf("tail loss occurred in %d/%d runs without truncation flag", losses, runs)
	}
}

// Child backgrounds a grandchild that inherits stdout and outlives it,
// then exits 0 within the timeout. Happy path sends no signal at all.
func TestCleanExitWithOutlivingGrandchild(t *testing.T) {
	dir := t.TempDir()
	done := make(chan struct{})
	go func() {
		defer close(done)
		result, err := (DirectRunner{}).Run(context.Background(), Request{
			Executable: "/bin/sh",
			Args:       []string{"-c", "sleep 4 & exit 0"},
			Dir:        dir, Env: []string{"PATH=/usr/bin:/bin"}, Timeout: time.Second,
		})
		fmt.Printf("returned after %s: err=%v exit=%d cancelled=%v timedout=%v cleanup=%v\n",
			time.Since(start), err, result.ExitCode, result.Cancelled, result.TimedOut, result.CleanupComplete)
	}()
	select {
	case <-done:
	case <-time.After(6 * time.Second):
		t.Fatal("Run did not return within 6s although the child exited cleanly at t=0 with a 1s timeout")
	}
}

var start = time.Now()
EOF
cd /tmp/opencode/drainsrace && go test -run 'TestBurstOutputTailLoss' -count=1 -v . 2>&1 | tail -20

