package main

import (
	"fmt"
	"io"
	"os"
	"time"
)

func main() {
	pr, pw, _ := os.Pipe()
	payload := make([]byte, 200_000)
	for i := range payload {
		payload[i] = 'x'
	}
	go func() {
		pw.Write(payload)
		pw.Close()
	}()
	total := 0
	buf := make([]byte, 32*1024)
	// simulate slow reader: delay first read so writer finishes + Wait-equivalent close happens
	time.Sleep(50 * time.Millisecond)
	closeErr := pr.Close() // emulate exec.Cmd.Wait closing the parent read end
	fmt.Printf("close err=%v\n", closeErr)
	for {
		n, err := pr.Read(buf)
		total += n
		if err != nil {
			fmt.Printf("read stopped: n=%d total=%d err=%v\n", n, total, err)
			break
		}
	}
	_, statErr := pr.Stat()
	fmt.Printf("post-close stat err=%v\n", statErr)
	io.Discard.Write(nil)
}
EOF
