			if relErr != nil {
				return relErr
			}
			if entry.IsDir() && entry.Name() == ".git" {
				return filepath.SkipDir
			}
			if rel == "." || entry.IsDir() {
				return nil
			}
			paths = append(paths, filepath.ToSlash(rel))
